System.out.println("result = " + result + ", i = " + i); // result = 13, i = 5

int x = 10;
x = x++;
System.out.println("x = " + x);

// 1. Fast parity check (Even vs Odd)
int n = 43;
boolean isOdd = (n & 1) == 1; // true (checks if lowest bit is 1)

// 2. Fast multiplication / division by powers of 2
int mult = 5 << 3; // 5 * (2^3) = 5 * 8 = 40
int div  = 40 >> 2; // 40 / (2^2) = 40 / 4 = 10

// 3. Check if number is a Power of Two
int num = 16;
boolean isPowerOfTwo = (num > 0) && ((num & (num - 1)) == 0); // true
// 16 is 10000, (16-1) is 01111 -> 10000 & 01111 = 00000

// 4. In-place variable swap without temporary variable
int a = 15, b = 27;
a ^= b;
b ^= a;
a ^= b;
System.out.println("a = " + a + ", b = " + b); // a = 27, b = 15

// 1. Arithmetic precedence: Multiplication (*) before Addition (+)
int res1 = 10 + 5 * 2;   // 10 + 10 = 20 (not 15 * 2 = 30)
int res2 = (10 + 5) * 2; // (15) * 2 = 30

// 2. Logical precedence: && before ||
boolean a = true, b = false, c = false;
boolean verdict1 = a || b && c;   // true || (false && false) -> true || false -> true
boolean verdict2 = (a || b) && c; // (true || false) && false -> true && false -> false

// 3. Bitwise vs Relational trap
int n = 6;
// boolean bad = n & 1 == 0; // COMPILE ERROR! '==' has higher precedence than '&', tries to evaluate '1 == 0' first!
boolean good = (n & 1) == 0; // true

int x = 2 + 3 * 4 / 2 - 1;
boolean cond = true || false && false;
System.out.println("x = " + x + ", cond = " + cond);

