System.out.print("Connecting");
System.out.print("...");
System.out.print(" [DONE]"); // Output: Connecting... [DONE]

// 2. println() appends a newline character
System.out.println(); // Prints empty newline
System.out.println("User: Vamsee");
System.out.println("Role: Admin");

