import java.util.Scanner;

public class UserRegistration {
    public static void main(String[] args) {
        // 1. Create Scanner tied to keyboard input (System.in)
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter your full name: ");
        String fullName = scanner.nextLine(); // Reads entire line including spaces

        System.out.print("Enter your age: ");
        int age = scanner.nextInt(); // Reads integer token

        System.out.print("Enter your GPA: ");
        double gpa = scanner.nextDouble(); // Reads floating point token

        System.out.println("\n--- Profile Created ---");
        System.out.printf("Name: %s%nAge: %d%nGPA: %.2f%n", fullName, age, gpa);

        // 2. Always close scanner when done
        scanner.close();
    }
}

