import java.util.Scanner;

Scanner sc = new Scanner(System.in);

// --- THE BUGGY CODE ---
System.out.print("Enter Age: ");
int age = sc.nextInt(); // User types '25' + ENTER. nextInt() reads 25, leaves '\n' in buffer

System.out.print("Enter City: ");
String city = sc.nextLine(); // BUG: Reads the leftover '\n' immediately, city becomes ""!

// --- SOLUTION 1: Consume the leftover newline ---
System.out.print("Enter Age: ");
int age1 = sc.nextInt();
sc.nextLine(); // Consumes the leftover '\n' from the buffer!
System.out.print("Enter City: ");
String city1 = sc.nextLine(); // Now correctly waits for user input!

// --- SOLUTION 2 (Industry Best Practice): Read everything as nextLine() and parse ---
System.out.print("Enter Age: ");
int age2 = Integer.parseInt(sc.nextLine().trim());
System.out.print("Enter City: ");
String city2 = sc.nextLine(); // Completely immune to buffer bugs!

import java.util.Scanner;

public class SafeInput {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int validAge = -1;

        // Loop until user enters a valid positive integer
        while (true) {
            System.out.print("Enter your age (1-120): ");
            if (sc.hasNextInt()) {
                validAge = sc.nextInt();
                if (validAge >= 1 && validAge <= 120) {
                    break; // Valid input received!
                } else {
                    System.out.println("Age out of range! Try again.");
                }
            } else {
                System.out.println("Invalid number! That wasn't an integer.");
                sc.next(); // Discard the invalid token from buffer
            }
        }

        System.out.println("Recorded Age: " + validAge);
        sc.close();
    }
}

// Buffer state after typing 42 and Enter:
// [ '4', '2', '\n' ]
// After nextInt(): [ '\n' ]
// After sc.nextLine(): [ ] (Buffer clean)

