public class MathUtils {
    // 1. Guard clauses for early exit in typed methods
    public static double divide(double numerator, double denominator) {
        if (denominator == 0.0) {
            System.out.println("Error: Division by zero");
            return 0.0; // Early exit with default fallback
        }
        return numerator / denominator; // Normal calculation path
    }

    // 2. Early exit in void methods
    public static void printUserGreeting(String username) {
        if (username == null || username.trim().isEmpty()) {
            return; // Exit immediately, print nothing
        }
        System.out.println("Hello, " + username + "!");
    }

    // 3. Exhaustive return paths across all branches
    public static String getSign(int n) {
        if (n > 0) return "Positive";
        if (n < 0) return "Negative";
        return "Zero"; // Guarantees a return in all possible paths
    }
}

