int negativeCount = 0;
for (int val : data) {
    if (val < 0) negativeCount++;
}
System.out.println("Negative count: " + negativeCount); // 2

// 2. SUMMATION & AVERAGE (Watch for integer truncation!)
long sum = 0L; // Use long to prevent integer overflow
for (int val : data) {
    sum += val;
}
double average = (double) sum / data.length; // Explicit cast for floating-point division
System.out.printf("Sum: %d, Average: %.2f%n", sum, average);

// 3. MIN / MAX TRACKER
int min = Integer.MAX_VALUE;
int max = Integer.MIN_VALUE;
for (int val : data) {
    if (val < min) min = val;
    if (val > max) max = val;
}
System.out.println("Min: " + min + ", Max: " + max); // Min: -8, Max: 50

// 4. PRODUCT ACCUMULATOR (Factorial of 5)
int n = 5;
long factorial = 1L; // Multiplicative identity = 1
for (int i = 1; i <= n; i++) {
    factorial *= i;
}
System.out.println("5! = " + factorial); // 120

