int n = 4;

// --- 1. RIGHT-ANGLED STAR TRIANGLE ---
// Row r has exactly r stars
System.out.println("--- Right-Angled Triangle ---");
for (int r = 1; r <= n; r++) {
    for (int c = 1; c <= r; c++) {
        System.out.print("* ");
    }
    System.out.println();
}

// --- 2. INVERTED STAR TRIANGLE ---
// Row r has (n - r + 1) stars
System.out.println("--- Inverted Triangle ---");
for (int r = 1; r <= n; r++) {
    for (int c = 1; c <= (n - r + 1); c++) {
        System.out.print("* ");
    }
    System.out.println();
}

// --- 3. CENTERED PYRAMID (Spaces + Stars) ---
// Spaces = (n - r), Stars = (2r - 1)
System.out.println("--- Centered Pyramid ---");
for (int r = 1; r <= n; r++) {
    for (int s = 1; s <= (n - r); s++) {
        System.out.print("  "); // 2 spaces for alignment
    }
    for (int star = 1; star <= (2 * r - 1); star++) {
        System.out.print("* ");
    }
    System.out.println();
}

