import java.util.Scanner;

public class ArrayInputDemo {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // 1. NUMERIC ARRAY INPUT
        System.out.print("Enter number of scores: ");
        int n = sc.nextInt();

