        System.out.println("Enter " + n + " integer scores:");
        for (int i = 0; i < scores.length; i++) {
            scores[i] = sc.nextInt();
        }

        // 2. STRING ARRAY INPUT (Clearing the phantom newline!)
        System.out.print("Enter number of student names: ");
        int nameCount = sc.nextInt();
        sc.nextLine(); // CRITICAL: Consume the lingering newline character!

        String[] names = new String[nameCount];
        System.out.println("Enter " + nameCount + " names:");
        for (int i = 0; i < names.length; i++) {
            names[i] = sc.nextLine();
        }
    }
}

