public class ArrayStats {
    public static void printStats(int[] arr) {
        // Defensive guard clause for empty arrays
        if (arr == null || arr.length == 0) {
            System.out.println("Cannot calculate stats for empty array.");
            return;
        }

        // 1. Initialize min and max with first element
        int min = arr[0];
        int max = arr[0];
        long sum = 0L; // Use long to prevent integer overflow on large datasets

        // 2. Single-pass traversal (O(N) time complexity)
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] < min) min = arr[i];
            if (arr[i] > max) max = arr[i];
            sum += arr[i];
        }

        // 3. Compute average with explicit floating-point promotion
        double average = (double) sum / arr.length;

        System.out.println("Min:     " + min);
        System.out.println("Max:     " + max);
        System.out.println("Sum:     " + sum);
        System.out.printf("Average: %.2f%n", average);
    }
}

