// 1. STRING LITERALS (Interned into String Pool)
String s1 = "Code";
String s2 = "Code";
System.out.println(s1 == s2); // TRUE! Both point to the same object in String Pool

// 2. NEW STRING() CONSTRUCTOR (Forces distinct Heap object allocation)
String s3 = new String("Code");
String s4 = new String("Code");
System.out.println(s1 == s3); // FALSE! s1 is in Pool, s3 is in general Heap
System.out.println(s3 == s4); // FALSE! s3 and s4 are distinct Heap objects
System.out.println(s1.equals(s3)); // TRUE! Both have identical content "Code"

// 3. THE intern() METHOD
// Retrieves the canonical representation from the String Pool
String s5 = s3.intern();
System.out.println(s1 == s5); // TRUE! s5 references the pooled object

