public class StringReversal {
    // Technique A: Built-in StringBuilder reverse (O(N) time, O(N) space)
    public static String reverseWithBuilder(String input) {
        if (input == null) return null;
        return new StringBuilder(input).reverse().toString();
    }

    // Technique B: Two-Pointer In-Place Array Swap (O(N) time, O(N) auxiliary space)
    public static String reverseTwoPointer(String input) {
        if (input == null) return null;
        char[] chars = input.toCharArray();
        int left = 0;
        int right = chars.length - 1;

        while (left < right) {
            char temp = chars[left];
            chars[left] = chars[right];
            chars[right] = temp;
            left++;
            right--;
        }
        return new String(chars);
    }

    public static void main(String[] args) {
        System.out.println(reverseWithBuilder("Pathway")); // "yawhtaP"
        System.out.println(reverseTwoPointer("Algorithm")); // "mhtiroglA"
    }
}

public class PalindromeChecker {
    public static boolean isPalindrome(String s) {
        if (s == null) return false;

        int left = 0;
        int right = s.length() - 1;

        while (left < right) {
            // Skip non-alphanumeric characters
            while (left < right && !Character.isLetterOrDigit(s.charAt(left))) {
                left++;
            }
            while (left < right && !Character.isLetterOrDigit(s.charAt(right))) {
                right--;
            }

            char leftChar  = Character.toLowerCase(s.charAt(left));
            char rightChar = Character.toLowerCase(s.charAt(right));

            if (leftChar != rightChar) {
                return false; // Mismatch found!
            }
            left++;
            right--;
        }
        return true; // All matched
    }

    public static void main(String[] args) {
        System.out.println(isPalindrome("A man, a plan, a canal: Panama")); // true
        System.out.println(isPalindrome("race a car"));                     // false
    }
}

