public class PassByValueDemo {
    // 1. Primitive parameter: Local copy modified
    public static void tryToModifyPrimitive(int x) {
        x = 999; // Changes ONLY local parameter x
    }

    // 2. Reference parameter: Modifying object contents
    public static void modifyArrayContent(int[] arr) {
        arr[0] = 999; // Mutates heap array element directly!
    }

    // 3. Reference parameter: Reassigning reference variable
    public static void tryToReassignReference(int[] arr) {
        arr = new int[] { 500, 600, 700 }; // Reassigns local pointer ONLY
    }

    public static void main(String[] args) {
        int num = 10;
        tryToModifyPrimitive(num);
        System.out.println("Primitive num after call: " + num); // 10 (UNCHANGED!)

        int[] numbers = { 1, 2, 3 };
        modifyArrayContent(numbers);
        System.out.println("Array[0] after content mod: " + numbers[0]); // 999 (CHANGED!)

        tryToReassignReference(numbers);
        System.out.println("Array[0] after reassignment: " + numbers[0]); // 999 (UNCHANGED!)
    }
}

