public class ReturnValuesDemo {
    // 1. Guard Clause Pattern (Early Exit for clean code)
    public static double calculateDiscount(double price, int customerYears, boolean isVip) {
        // Guard clause: Invalid input
        if (price <= 0) {
            return 0.0; // Early exit
        }
        // Guard clause: VIP status
        if (isVip) {
            return price * 0.25;
        }
        // Standard tier calculation
        if (customerYears >= 5) {
            return price * 0.15;
        }
        return price * 0.05; // Base fallback discount
    }

    // 2. Returning an Array / Object
    public static int[] getMinMax(int[] numbers) {
        if (numbers == null || numbers.length == 0) {
            return new int[] { 0, 0 };
        }
        int min = numbers[0];
        int max = numbers[0];
        for (int n : numbers) {
            if (n < min) min = n;
            if (n > max) max = n;
        }
        return new int[] { min, max }; // Bundled array return
    }

    public static void main(String[] args) {
        double discount = calculateDiscount(200.0, 6, false); // 30.0
        System.out.println("Discount: $" + discount);

        int[] stats = getMinMax(new int[] { 45, 12, 89, 3, 67 });
        System.out.println("Min: " + stats[0] + ", Max: " + stats[1]); // Min: 3, Max: 89
    }
}

class Grader {
    public static char getGrade(int score) {
        if (score >= 90) return 'A';
        if (score >= 80) return 'B';
        if (score >= 70) return 'C';
        if (score >= 60) return 'D';
        return 'F';
    }
    public static void main(String[] args) {
        System.out.println("Grade: " + getGrade(85));
    }
}

