public class MemoryMapDemo {
    // 1. METASPACE: Class metadata, bytecode, and static variables
    public static final String APP_NAME = "StudyHubEngine";
    private static int totalInstances = 0;

    // 2. HEAP: Instance fields stored inside the object payload
    private int userId;
    private String username;

    public MemoryMapDemo(int id, String name) {
        this.userId = id;
        this.username = name; // Reference to String on Heap
        totalInstances++;
    }

    // 3. JVM STACK: Local variables allocated inside method stack frame
    public static void main(String[] args) {
        int localCounter = 42; // Primitive: stored directly in Stack Frame

        // 'userRef' pointer lives in Stack Frame; 'new MemoryMapDemo' payload lives in Heap
        MemoryMapDemo userRef = new MemoryMapDemo(101, "Alice");

        System.out.println(APP_NAME + " | User: " + userRef.username);
    }
}

class MemoryTest {
    int instanceNum = 10; // Heap
    static int globalCount = 99; // Metaspace

    public static void compute(int param) { // Stack
        int localVar = 50; // Stack
        MemoryTest obj = new MemoryTest(); // obj reference: Stack, instance: Heap
        System.out.println(localVar + obj.instanceNum + param);
    }

    public static void main(String[] args) {
        compute(5);
    }
}

public class StackTraceDemo {
    public static int multiply(int x, int y) {
        // Frame 3: multiply(x=6, y=7)
        int product = x * y; // Pushes x and y to Operand Stack, executes 'imul', stores in product
        return product;
    }

    public static int calculateSquare(int val) {
        // Frame 2: calculateSquare(val=6)
        int result = multiply(val, 7); // Pauses Frame 2; pushes Frame 3
        return result;
    }

    public static void main(String[] args) {
        // Frame 1: main(args)
        int num = 6;
        int answer = calculateSquare(num); // Pauses Frame 1; pushes Frame 2
        System.out.println("Answer: " + answer); // 42
    }
}

class StackOrder {
    public static int stepA() { return 10; }
    public static int stepB() { return stepA() + 5; }
    public static void main(String[] args) {
        System.out.println(stepB());
    }
}

public class HeapStructureDemo {
    // Object payload lives on the HEAP
    static class Student {
        int id;             // 4 bytes primitive
        String name;        // 4/8 bytes reference pointer to String object
        double gpa;         // 8 bytes primitive

        Student(int id, String name, double gpa) {
            this.id = id;
            this.name = name;
            this.gpa = gpa;
        }
    }

    public static void main(String[] args) {
        // s1 pointer lives on Stack; Student object lives on Heap
        Student s1 = new Student(101, "Bob", 3.85);

        // s2 gets a COPY of the pointer; points to the EXACT SAME Heap object
        Student s2 = s1;
        s2.gpa = 4.0;

        System.out.println("s1 GPA: " + s1.gpa); // 4.0 (Mutated via s2!)
    }
}

class ObjectCounter {
    public static void main(String[] args) {
        String a = new String("Hello"); // Heap object
        String b = new String("World"); // Heap object
        int[] arr = new int[5];          // Heap array object
        int x = 100;                     // Stack primitive
        System.out.println("Allocated successfully!");
    }
}

public class GCDemo {
    static class Node {
        String name;
        Node next;
        Node(String name) { this.name = name; }
    }

    public static void main(String[] args) {
        // Case 1: Nulling Reference
        Node a = new Node("Alpha");
        a = null; // "Alpha" is now disconnected from GC Roots -> ELIGIBLE FOR GC

        // Case 2: Reassigning Reference
        Node b = new Node("Beta");
        b = new Node("Gamma"); // "Beta" has no references left -> ELIGIBLE FOR GC

        // Case 3: Circular Island of Isolation
        Node x = new Node("X");
        Node y = new Node("Y");
        x.next = y; // x points to y
        y.next = x; // y points to x
        x = null;   // Sever root to x
        y = null;   // Sever root to y
        // Both x and y point to each other, but NEITHER is reachable from a GC Root!
        // -> BOTH ARE ELIGIBLE FOR GC!
    }
}

class GCTest {
    public static void main(String[] args) {
        String s1 = new String("Data1");
        String s2 = new String("Data2");
        s1 = s2;
        // How many objects are eligible for GC here?
        System.out.println(s1 + " " + s2);
    }
}

public class JITOptimizationDemo {
    // Small helper method (prime candidate for JIT Inlining)
    public static int add(int a, int b) {
        return a + b;
    }

    public static void main(String[] args) {
        long total = 0;

        // JVM Warm-up: This loop runs 10,000,000 times (HOT SPOT!)
        for (int i = 0; i < 10_000_000; i++) {
            // BEFORE JIT: Pushes stack frame for add(total, i), executes, pops stack frame
            // AFTER JIT (Inlining): Replaces method call with raw CPU addition: total += i
            total = add((int) total, i);
        }

        System.out.println("Total: " + total);
    }
}

class DeadCodeTest {
    public static void main(String[] args) {
        boolean debug = false;
        int x = 10;
        if (debug) {
            x = 999; // Never executes
        }
        System.out.println("x = " + x);
    }
}

// Java Source Code:
// public static int compute(int a, int b) {
//     int c = a + b;
//     return c * 2;
// }

// Disassembled Java Bytecode (javap -c):
// 0: iload_0        // Push parameter 'a' (slot 0) onto Operand Stack
// 1: iload_1        // Push parameter 'b' (slot 1) onto Operand Stack
// 2: iadd           // Pop both, add on CPU ALU, push sum (a+b)
// 3: istore_2       // Pop sum into local variable 'c' (slot 2)
// 4: iload_2        // Push 'c' onto Operand Stack
// 5: iconst_2       // Push constant integer 2 onto Operand Stack
// 6: imul           // Pop c and 2, multiply, push product
// 7: ireturn        // Return top of stack (int product)

class BytecodeTrace {
    public static int calc() {
        int x = 5;
        int y = 3;
        return (x + y) * 2;
    }
    public static void main(String[] args) {
        System.out.println(calc());
    }
}

public class ProblemSolvingCaseStudy {
    // === STAGE 1: Brute Force Approach (O(N) time) ===
    public static boolean isPrimeBruteForce(int n) {
        if (n < 2) return false;
        for (int i = 2; i < n; i++) {
            if (n % i == 0) return false; // Found factor
        }
        return true;
    }

    // === STAGE 2: Optimized Approach (O(sqrt(N)) time) ===
    // Mathematical Invariant: If n = a * b, at least one factor <= sqrt(n)
    public static boolean isPrimeOptimized(int n) {
        if (n < 2) return false;
        if (n == 2 || n == 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false; // Filter evens & multiples of 3

        // Test divisors up to sqrt(n) stepping by 6 (6k +/- 1)
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println("isPrime(29): " + isPrimeOptimized(29));   // true
        System.out.println("isPrime(100): " + isPrimeOptimized(100)); // false
        System.out.println("isPrime(1): " + isPrimeOptimized(1));     // false (Edge case!)
    }
}

class SecondLargest {
    public static int findSecond(int[] arr) {
        if (arr == null || arr.length < 2) return -1;
        int largest = Integer.MIN_VALUE;
        int second = Integer.MIN_VALUE;
        for (int num : arr) {
            if (num > largest) {
                second = largest;
                largest = num;
            } else if (num > second && num != largest) {
                second = num;
            }
        }
        return (second == Integer.MIN_VALUE) ? -1 : second;
    }
    public static void main(String[] args) {
        System.out.println(findSecond(new int[] { 10, 20, 4, 45, 99, 99 })); // 45
    }
}

public class DecompositionDemo {
    // === BAD APPROACH: 40-line messy monolithic blob ===
    // Hard to read, hard to debug, impossible to unit test individual rules.

    // === GOOD APPROACH: Modular Decomposed Pipeline ===

    // Sub-step 1: Clean and normalize text
    public static String cleanInput(String text) {
        if (text == null) return "";
        return text.trim().toLowerCase();
    }

    // Sub-step 2: Validate structural rules
    public static boolean hasValidLength(String text, int min, int max) {
        return text.length() >= min && text.length() <= max;
    }

    public static boolean containsSpecialChar(String text) {
        for (int i = 0; i < text.length(); i++) {
            char ch = text.charAt(i);
            if (!Character.isLetterOrDigit(ch)) return true;
        }
        return false;
    }

    // Master Orchestrator Method
    public static boolean validatePassword(String rawPassword) {
        String cleaned = cleanInput(rawPassword);
        if (!hasValidLength(cleaned, 8, 30)) return false;
        if (!containsSpecialChar(cleaned)) return false;
        return true; // Passed all stages
    }

    public static void main(String[] args) {
        System.out.println(validatePassword("Pass@1234")); // true
        System.out.println(validatePassword("short"));     // false
    }
}

class WordProcessor {
    public static String[] splitWords(String text) {
        if (text == null || text.trim().isEmpty()) return new String[0];
        return text.trim().split("\\s+");
    }
    public static int countLongWords(String text, int minLength) {
        String[] words = splitWords(text);
        int count = 0;
        for (String w : words) {
            if (w.length() >= minLength) count++;
        }
        return count;
    }
    public static void main(String[] args) {
        System.out.println("Long words (>=5): " + countLongWords("Java provides clean modular methods for engineering", 5));
    }
}

