public class SmartphoneDemo {
    static class Smartphone {
        // 1. Instance Fields (State)
        String brand;
        int batteryLevel = 100; // Explicit default
        boolean isScreenOn = false;

        // 2. Instance Methods (Behavior)
        void pressPowerButton() {
            isScreenOn = !isScreenOn;
            System.out.println(brand + " screen is now: " + (isScreenOn ? "ON" : "OFF"));
        }

        boolean launchApp(String appName, int batteryCost) {
            if (!isScreenOn) {
                System.out.println("Cannot launch " + appName + ": Screen is OFF!");
                return false;
            }
            if (batteryLevel < batteryCost) {
                System.out.println("Battery too low to launch " + appName);
                return false;
            }
            batteryLevel -= batteryCost;
            System.out.println("Launched " + appName + ". Battery now: " + batteryLevel + "%");
            return true;
        }

        void charge() {
            batteryLevel = 100;
            System.out.println(brand + " fully recharged to 100%.");
        }
    }

