        phone.brand = "Pixel 8";

        phone.launchApp("Maps", 15);      // Fails: Screen is OFF
        phone.pressPowerButton();         // Screen turns ON
        phone.launchApp("Maps", 15);      // Success: Battery drops to 85%
    }
}

