public class ThisKeywordDemo {
    static class UserProfile {
        private String username;
        private String email;
        private int age;

        // USE CASE 2: Constructor Chaining using this(...)
        public UserProfile(String username) {
            this(username, "unknown@domain.com", 18); // Delegates to master constructor
        }

        // Master Constructor
        public UserProfile(String username, String email, int age) {
            // USE CASE 1: Resolving Variable Shadowing
            this.username = username;
            this.email = email;
            this.age = age;
        }

        // USE CASE 3: Method Chaining (Fluent Builder Pattern)
        public UserProfile setEmail(String email) {
            this.email = email;
            return this; // Returns reference to current object
        }

        public UserProfile setAge(int age) {
            this.age = age;
            return this;
        }

        public void printInfo() {
            System.out.println(this.username + " (" + this.age + ") - " + this.email);
        }
    }

    public static void main(String[] args) {
        // Fluent chained method calls
        UserProfile user = new UserProfile("vamsee")
                .setEmail("vamsee@studyhub.dev")
                .setAge(24);

        user.printInfo(); // vamsee (24) - vamsee@studyhub.dev
    }
}

