    int val = 10;
    void setVal(int val) {
        val = val; // Parameter assigned to itself! 'this.val' untouched
    }
    public static void main(String[] args) {
        ShadowingBug obj = new ShadowingBug();
        obj.setVal(99);
        System.out.println(obj.val);
    }
}

