public class ObjectMemoryModelDemo {
    static class Box {
        int width;
        Box(int w) { this.width = w; }
    }

    // 1. Mutates object payload through copied reference
    public static void modifyPayload(Box b) {
        b.width = 99; // Mutates original Heap object
    }

    // 2. Reassigns local pointer copy (Does NOT affect caller!)
    public static void reassignReference(Box b) {
        b = new Box(500); // Only changes local stack parameter 'b'
    }

    public static void main(String[] args) {
        // Step 1: Allocate Box on Heap
        Box box1 = new Box(10);

        // Step 2: Aliasing
        Box box2 = box1; // Both box1 and box2 point to 0x1A2B
        box2.width = 20;
        System.out.println("box1.width after box2 change: " + box1.width); // 20!

        // Step 3: Method mutation
        modifyPayload(box1);
        System.out.println("box1.width after modifyPayload: " + box1.width); // 99!

        // Step 4: Method reassignment
        reassignReference(box1);
        System.out.println("box1.width after reassignReference: " + box1.width); // Still 99!
    }
}

