public class EncapsulationDemo {
    // === BAD DESIGN: Unencapsulated (Public Fields) ===
    static class VulnerableAccount {
        public double balance; // DISASTER: Anyone can do account.balance = -999999.0
    }

    // === GOOD DESIGN: Properly Encapsulated ===
    static class SecureAccount {
        private String accountNumber;
        private double balance;
        private static final double MIN_BALANCE = 0.0;

        public SecureAccount(String accNo, double initialDeposit) {
            this.accountNumber = accNo;
            if (initialDeposit < MIN_BALANCE) {
                throw new IllegalArgumentException("Initial deposit cannot be negative.");
            }
            this.balance = initialDeposit;
        }

        // Read-only accessor
        public double getBalance() {
            return this.balance;
        }

        // Controlled mutator with validation
        public boolean withdraw(double amount) {
            if (amount <= 0) {
                throw new IllegalArgumentException("Withdrawal amount must be positive.");
            }
            if (amount > this.balance) {
                System.out.println("Transaction Denied: Insufficient funds.");
                return false;
            }
            this.balance -= amount;
            System.out.println("Withdrew $" + amount + ". New Balance: $" + this.balance);
            return true;
        }
    }

    public static void main(String[] args) {
        SecureAccount acc = new SecureAccount("ACC-9921", 1000.0);
        acc.withdraw(400.0);  // Success: New Balance = $600.0
        acc.withdraw(1200.0); // Denied: Insufficient funds
        System.out.println("Final Verified Balance: $" + acc.getBalance()); // $600.0
    }
}

