import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class ImmutabilityDemo {
    // === 1. CLASSIC IMMUTABLE CLASS (Pre-Java 14 Pattern) ===
    public static final class ImmutableStudent {
        private final int id;
        private final String name;
        private final List<String> subjects;

        public ImmutableStudent(int id, String name, List<String> subjects) {
            this.id = id;
            this.name = name;
            // Defensive copy on input
            this.subjects = (subjects != null) ? new ArrayList<>(subjects) : new ArrayList<>();
        }

        public int getId() { return id; }
        public String getName() { return name; }

        // Defensive unmodifiable view on output
        public List<String> getSubjects() {
            return Collections.unmodifiableList(subjects);
        }
    }

    // === 2. MODERN JAVA RECORD (Java 14+) ===
    // Automatically generates: private final fields, constructor, getters, equals(), hashCode(), and toString()!
    public record StudentRecord(int id, String name, List<String> subjects) {
        // Compact Canonical Constructor with defensive copy
        public StudentRecord {
            subjects = (subjects != null) ? List.copyOf(subjects) : List.of();
        }
    }

    public static void main(String[] args) {
        List<String> subs = new ArrayList<>(List.of("Math", "CS"));
        ImmutableStudent student1 = new ImmutableStudent(101, "Alice", subs);
        StudentRecord student2 = new StudentRecord(102, "Bob", subs);

        System.out.println(student1.getName() + ": " + student1.getSubjects());
        System.out.println(student2.name() + ": " + student2.subjects());
    }
}

