import java.util.Objects;
import java.util.HashSet;
import java.util.Set;

public class ObjectClassDemo {
    static class User {
        private final int id;
        private final String email;

        public User(int id, String email) {
            this.id = id;
            this.email = email;
        }

        // 1. OVERRIDING toString() for human-readable debugging
        @Override
        public String toString() {
            return "User[id=" + id + ", email='" + email + "']";
        }

        // 2. OVERRIDING equals(Object o) for logical value comparison
        @Override
        public boolean equals(Object o) {
            if (this == o) return true; // Exact same reference
            if (o == null || getClass() != o.getClass()) return false; // Null or different type
            User user = (User) o; // Safe downcast
            return id == user.id && Objects.equals(email, user.email);
        }

        // 3. OVERRIDING hashCode() matching equals() fields
        @Override
        public int hashCode() {
            return Objects.hash(id, email);
        }
    }

    public static void main(String[] args) {
        User u1 = new User(101, "alice@domain.com");
        User u2 = new User(101, "alice@domain.com");

        System.out.println(u1); // User[id=101, email='alice@domain.com']
        System.out.println("== Identity Check: " + (u1 == u2)); // false (different heap memory)
        System.out.println("equals() Value Check: " + u1.equals(u2)); // true!

        // HashSet relies on hashCode() and equals() to prevent duplicates
        Set<User> set = new HashSet<>();
        set.add(u1);
        set.add(u2); // Duplicate recognized and rejected!
        System.out.println("Set Size: " + set.size()); // Exactly 1!
    }
}

