        System.out.println("Sum: " + calc.add(2.5, 3.5));     // Matches add(double, double)

        // Runtime polymorphic dispatch: Reference type is AudioPlayer, but heap objects differ
        AudioPlayer p1 = new SpotifyPlayer();
        AudioPlayer p2 = new PodcastPlayer();

        p1.playMedia(); // Streaming lossless FLAC audio via Spotify API.
        p2.playMedia(); // Playing podcast with 1.5x vocal speed boost.
