public class OverloadResolutionDemo {
    // Tier 1: Exact Match for int
    static void process(int x) { System.out.println("1. Exact Match (int): " + x); }

    // Tier 2: Primitive Widening (int -> long)
    static void process(long x) { System.out.println("2. Primitive Widening (long): " + x); }

    // Tier 3: Autoboxing (int -> Integer)
    static void process(Integer x) { System.out.println("3. Autoboxing (Integer): " + x); }

    // Tier 4: Varargs (int...)
    static void process(int... x) { System.out.println("4. Varargs (int...): " + x[0]); }

