public class DowncastingPatternDemo {
    static class Employee { String name = "Alice"; }
    static class Developer extends Employee {
        void writeJavaCode() { System.out.println(name + " is writing high-performance backend code."); }
    }
    static class Designer extends Employee {
        void createMockup() { System.out.println(name + " is creating Figma UI designs."); }
    }

    // 1. CLASSIC APPROACH (Pre-Java 14: Verbose instanceof + Manual Downcast)
    public static void processEmployeeClassic(Employee emp) {
        if (emp instanceof Developer) {
            Developer dev = (Developer) emp; // Redundant manual cast!
            dev.writeJavaCode();
        } else if (emp instanceof Designer) {
            Designer des = (Designer) emp;
            des.createMockup();
        }
    }

    // 2. MODERN APPROACH (Java 14+ Pattern Matching for instanceof)
    // Automatically tests AND casts in a single clean expression!
    public static void processEmployeeModern(Employee emp) {
        if (emp instanceof Developer dev) {
            dev.writeJavaCode(); // 'dev' is in scope and already cast!
        } else if (emp instanceof Designer des) {
            des.createMockup();
        }
    }

    public static void main(String[] args) {
        Employee emp1 = new Developer();
        Employee emp2 = new Designer();

        processEmployeeModern(emp1); // Alice is writing high-performance backend code.
        processEmployeeModern(emp2); // Alice is creating Figma UI designs.
    }
}

