public class StrategyPatternDemo {
    // 1. THE STRATEGY INTERFACE
    interface NotificationStrategy {
        void sendAlert(String recipient, String message);
    }

    // 2. CONCRETE STRATEGY A: Email
    static class EmailStrategy implements NotificationStrategy {
        @Override
        public void sendAlert(String recipient, String message) {
            System.out.println("[EMAIL SMTP -> " + recipient + "]: " + message);
        }
    }

    // 3. CONCRETE STRATEGY B: SMS (Twilio)
    static class SMSStrategy implements NotificationStrategy {
        @Override
        public void sendAlert(String recipient, String message) {
            System.out.println("[SMS GATEWAY -> " + recipient + "]: " + message);
        }
    }

    // 4. CONCRETE STRATEGY C: Push Notification (Firebase FCM)
    static class PushStrategy implements NotificationStrategy {
        @Override
        public void sendAlert(String recipient, String message) {
            System.out.println("[PUSH NOTIFICATION -> Device Token " + recipient + "]: " + message);
        }
    }

    // 5. THE CONTEXT (Orchestrator holding polymorphic strategy reference)
    static class AlertService {
        private NotificationStrategy strategy;

        public AlertService(NotificationStrategy initialStrategy) {
            this.strategy = initialStrategy;
        }

        // Dynamic Strategy Switcher at runtime
        public void setStrategy(NotificationStrategy newStrategy) {
            this.strategy = newStrategy;
        }

        public void triggerSecurityAlert(String user, String alertText) {
            // Polymorphic delegation
            strategy.sendAlert(user, alertText);
        }
    }

    public static void main(String[] args) {
        AlertService service = new AlertService(new EmailStrategy());
        service.triggerSecurityAlert("alice@corp.com", "Suspicious login detected from IP 192.168.1.1");

        // Swapping strategy dynamically to SMS for critical urgent alert
        service.setStrategy(new SMSStrategy());
        service.triggerSecurityAlert("+1-555-0199", "URGENT: Password reset code is 884920");
    }
}

