public class AbstractionOverviewDemo {
    // 1. THE ABSTRACT INTERFACE (Defines WHAT happens)
    interface AudioDecoder {
        byte[] decodeAudioStream(byte[] rawCompressedData);
    }

    // 2. CONCRETE IMPLEMENTATION A (Hidden HOW: Complex MP3 Huffman decoding)
    static class Mp3Decoder implements AudioDecoder {
        @Override
        public byte[] decodeAudioStream(byte[] rawData) {
            System.out.println("Executing MP3 discrete cosine transform & decompression...");
            return new byte[]{1, 0, 1, 1}; // Decoded PCM bytes
        }
