    // 3. CONCRETE IMPLEMENTATION B (Hidden HOW: FLAC Lossless algorithm)
    static class FlacDecoder implements AudioDecoder {
        @Override
        public byte[] decodeAudioStream(byte[] rawData) {
            System.out.println("Executing FLAC linear prediction & lossless decompression...");
            return new byte[]{1, 1, 1, 1};
        }
    }

    // 4. CLIENT SYSTEM: Relies strictly on the Abstraction
    static class MusicPlayer {
        public static void playTrack(AudioDecoder decoder, byte[] trackData) {
            byte[] pcmStream = decoder.decodeAudioStream(trackData);
            System.out.println("Pumping " + pcmStream.length + " PCM audio frames to speakers.\n");
        }
    }

    public static void main(String[] args) {
        byte[] sampleData = new byte[]{10, 20, 30};

