public class InterfaceDemo {
    // 1. Interface 1: Flyable contract
    interface Flyable {
        int MAX_ALTITUDE_METERS = 10000; // Implicitly public static final
        void takeOff();                  // Implicitly public abstract
        void land();
    }

    // 2. Interface 2: GPSNavigable contract
    interface GPSNavigable {
        void navigateToCoordinates(double lat, double lon);
    }

    // 3. Interface 3: CameraEquipped contract
    interface CameraEquipped {
        void capture4KPhoto();
    }

    // CONCRETE CLASS implementing MULTIPLE INTERFACES
    static class AutonomousDrone implements Flyable, GPSNavigable, CameraEquipped {
        private String modelName;

        public AutonomousDrone(String model) { this.modelName = model; }

        // Implementing Flyable
        @Override
        public void takeOff() { System.out.println(modelName + " rotors spinning up. Taking off!"); }

        @Override
        public void land() { System.out.println(modelName + " landing safely on landing pad."); }

        // Implementing GPSNavigable
        @Override
        public void navigateToCoordinates(double lat, double lon) {
            System.out.println(modelName + " routing to Lat: " + lat + ", Lon: " + lon);
        }

        // Implementing CameraEquipped
        @Override
        public void capture4KPhoto() {
            System.out.println(modelName + " gimbal stabilized. 4K Photo captured!");
        }
    }

