public class ModernInterfaceDemo {
    interface Logger {
        // 1. Abstract method (Must be implemented)
        void logRaw(String formattedMessage);

        // 2. Default method (Java 8+): Provides default behavior with fallback
        default void logInfo(String message) {
            logWithPrefix("INFO", message); // Calls private helper
        }

        default void logError(String message) {
            logWithPrefix("ERROR", message);
        }

        // 3. Private helper method (Java 9+): Shared internal logic
        private void logWithPrefix(String level, String msg) {
            String timestamp = java.time.LocalTime.now().toString();
            logRaw("[" + timestamp + "] [" + level + "] " + msg);
        }

        // 4. Static utility method (Java 8+)
        static Logger getConsoleLogger() {
            return message -> System.out.println(message);
        }
    }

    public static void main(String[] args) {
        // Using static factory method
        Logger consoleLog = Logger.getConsoleLogger();
        consoleLog.logInfo("Server initialized on port 8080.");
        consoleLog.logError("Database timeout after 5000ms.");
    }
}

