import java.util.function.Predicate;
import java.util.function.Function;
import java.util.function.Consumer;
import java.util.function.Supplier;

public class FunctionalInterfacesDemo {
    public static void main(String[] args) {
        // 1. PREDICATE<T>: Takes T -> returns boolean (Condition testing)
        Predicate<String> isValidEmail = email -> email != null && email.contains("@");
        System.out.println("Is valid: " + isValidEmail.test("alice@studyhub.dev")); // true

        // 2. FUNCTION<T, R>: Takes T -> returns R (Transformation)
        Function<String, Integer> stringLength = String::length; // Method reference
        System.out.println("Length: " + stringLength.apply("Antigravity")); // 11

        // 3. CONSUMER<T>: Takes T -> returns void (Side effect)
        Consumer<String> logger = msg -> System.out.println("[LOG] " + msg);
        logger.accept("Database connection established.");

        // 4. SUPPLIER<T>: Takes nothing -> returns T (Factory / Generator)
        Supplier<Double> randomScore = () -> Math.random() * 100.0;
        System.out.println("Generated: " + randomScore.get());
    }
}

