public class RecordDeepDiveDemo {
    // RECORD DECLARATION
    public record OrderTransaction(String orderId, double amount, String currency) {
        // COMPACT CONSTRUCTOR: Custom validation without repeating field assignments!
        public OrderTransaction {
            if (orderId == null || orderId.isBlank()) {
                throw new IllegalArgumentException("Order ID cannot be blank.");
            }
            if (amount <= 0.0) {
                throw new IllegalArgumentException("Amount must be positive.");
            }
            // Normalization: Field assignments (this.orderId = orderId) happen AUTOMATICALLY!
            currency = (currency != null) ? currency.toUpperCase() : "USD";
        }

        // Custom instance method
        public boolean isHighValue() {
            return this.amount >= 1000.0;
        }
    }

    public static void main(String[] args) {
        OrderTransaction tx1 = new OrderTransaction("TX-9901", 1500.0, "eur");
        OrderTransaction tx2 = new OrderTransaction("TX-9901", 1500.0, "EUR");

        // Component accessors (no 'get' prefix)
        System.out.println("ID: " + tx1.orderId() + " | Currency: " + tx1.currency()); // TX-9901 | EUR
        System.out.println("Is High Value: " + tx1.isHighValue()); // true

        // Value-based equality
        System.out.println("tx1.equals(tx2): " + tx1.equals(tx2)); // true!
        System.out.println("toString(): " + tx1); // OrderTransaction[orderId=TX-9901, amount=1500.0, currency=EUR]
    }
}

