public class GenericsBasicsDemo {
    // 1. GENERIC CLASS with 2 type parameters <K, V>
    static class KeyValuePair<K, V> {
        private K key;
        private V value;

        public KeyValuePair(K k, V v) {
            this.key = k;
            this.value = v;
        }

        public K getKey() { return key; }
        public V getValue() { return value; }
    }

    // 2. BOUNDED GENERIC METHOD (<T extends Number>): Only accepts numeric types!
    public static <T extends Number> double calculateSum(T num1, T num2) {
        // Can safely call Number methods like doubleValue()!
        return num1.doubleValue() + num2.doubleValue();
    }

    public static void main(String[] args) {
        // Type-safe generic pair
        KeyValuePair<String, Integer> studentRank = new KeyValuePair<>("Alice", 1);
        System.out.println(studentRank.getKey() + ": Rank #" + studentRank.getValue());

        // Bounded generic method
        double sumInt = calculateSum(10, 25);
        double sumDouble = calculateSum(4.5, 9.2);
        System.out.println("Sum Ints: " + sumInt + " | Sum Doubles: " + sumDouble);
    }
}

class Box<T> {
