// --- CLEAN ISP DESIGN: Role-Based Segregated Interfaces ---
interface Printable {
    void print();
}

interface Scannable {
    void scan();
}

interface Faxable {
    void fax();
}

// Standard Printer only implements what it supports
class StandardOfficePrinter implements Printable, Scannable {
    public void print() { System.out.println("Standard printer: Printing..."); }
    public void scan() { System.out.println("Standard printer: Scanning..."); }
}

// High-end Enterprise Machine implements all roles
class EnterpriseMultiFunctionDevice implements Printable, Scannable, Faxable {
    public void print() { System.out.println("Enterprise: High-speed Print..."); }
    public void scan() { System.out.println("Enterprise: 600 DPI Scan..."); }
    public void fax() { System.out.println("Enterprise: Faxing abroad..."); }
}

public class ISPDemo {
