public class DatabaseConnectionPool {
    // volatile prevents Instruction Reordering by JVM during object initialization
    private static volatile DatabaseConnectionPool instance;
    private String connectionUrl;

    // 1. Private constructor prevents direct instantiation with 'new'
    private DatabaseConnectionPool() {
        this.connectionUrl = "jdbc:postgresql://db.studyhub.internal:5432/main";
        System.out.println("Initializing expensive database connection pool...");
    }

    // 2. Thread-safe Double-Checked Locking
    public static DatabaseConnectionPool getInstance() {
        if (instance == null) { // First check (no locking overhead for existing instance)
            synchronized (DatabaseConnectionPool.class) {
                if (instance == null) { // Second check (ensures only ONE thread initializes)
                    instance = new DatabaseConnectionPool();
                }
            }
        }
        return instance;
    }

    public void executeQuery(String sql) {
        System.out.println("Executing on " + connectionUrl + ": " + sql);
    }
}

// Usage demonstration
class SingletonDemo {
    public static void main(String[] args) {
        DatabaseConnectionPool pool1 = DatabaseConnectionPool.getInstance();
        DatabaseConnectionPool pool2 = DatabaseConnectionPool.getInstance();

        System.out.println("Are both references identical? " + (pool1 == pool2)); // true
        pool1.executeQuery("SELECT * FROM users;");
    }
}

