class MinHeap {
    private int[] a = new int[16];
    private int size = 0;

    void add(int x) {                                        // O(log n)
        if (size == a.length) a = Arrays.copyOf(a, size * 2);
        a[size] = x;
        int i = size++;
        while (i > 0 && a[(i - 1) / 2] > a[i]) {             // sift up
            swap(i, (i - 1) / 2);
            i = (i - 1) / 2;
        }
    }

    int poll() {                                             // O(log n), removes the min
        int top = a[0];
        a[0] = a[--size];                                    // move the last element to the root
        int i = 0;
        while (true) {                                       // sift down
            int l = 2 * i + 1, r = l + 1, s = i;
            if (l < size && a[l] < a[s]) s = l;
            if (r < size && a[r] < a[s]) s = r;
            if (s == i) break;
            swap(i, s);
            i = s;
        }
        return top;
    }

    boolean isEmpty() { return size == 0; }
    private void swap(int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }
}
// add 5, 3, 8, 1, 9, 2 then poll repeatedly -> 1, 2, 3, 5, 8, 9

PriorityQueue<Integer> minHeap = new PriorityQueue<>();                   // smallest first
PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
PriorityQueue<int[]> byDist = new PriorityQueue<>((a, b) -> a[1] - b[1]); // custom comparator

minHeap.offer(5); minHeap.offer(1); minHeap.offer(3);
minHeap.peek();   // 1
minHeap.poll();   // 1

static int findKthLargest(int[] nums, int k) {
    PriorityQueue<Integer> pq = new PriorityQueue<>();      // holds the k largest seen so far
    for (int x : nums) {
        pq.offer(x);
        if (pq.size() > k) pq.poll();                        // drop the smallest
    }
    return pq.peek();                                        // smallest of the k largest
}
// {3, 2, 1, 5, 6, 4}, k = 2 -> 5

static int[] topKFrequent(int[] nums, int k) {
    Map<Integer, Integer> freq = new HashMap<>();
    for (int x : nums) freq.merge(x, 1, Integer::sum);
    PriorityQueue<Integer> pq = new PriorityQueue<>((x, y) -> freq.get(x) - freq.get(y));
    for (int x : freq.keySet()) {
        pq.offer(x);
        if (pq.size() > k) pq.poll();                         // evict the least frequent
    }
    int[] res = new int[k];
    for (int i = k - 1; i >= 0; i--) res[i] = pq.poll();     // most frequent first
    return res;
}
// {1, 1, 1, 2, 2, 3}, k = 2 -> {1, 2}

static List<Integer> mergeKSorted(List<int[]> lists) {
    // heap entries: {value, which list, index within that list}
    PriorityQueue<int[]> pq = new PriorityQueue<>((x, y) -> x[0] - y[0]);
    for (int i = 0; i < lists.size(); i++)
        if (lists.get(i).length > 0) pq.offer(new int[]{lists.get(i)[0], i, 0});
    List<Integer> out = new ArrayList<>();
    while (!pq.isEmpty()) {
        int[] t = pq.poll();
        out.add(t[0]);
        int[] src = lists.get(t[1]);
        if (t[2] + 1 < src.length) pq.offer(new int[]{src[t[2] + 1], t[1], t[2] + 1});
    }
    return out;
}
// [1,4,5], [1,3,4], [2,6] -> [1, 1, 2, 3, 4, 4, 5, 6]

int n = 6;
int[][] edges = {{0, 1}, {0, 2}, {1, 3}, {2, 4}, {3, 5}, {4, 5}};
List<List<Integer>> adj = new ArrayList<>();
for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
for (int[] e : edges) {
    adj.get(e[0]).add(e[1]);
    adj.get(e[1]).add(e[0]);      // omit this line for a directed graph
}
// Weighted: List<List<int[]>> with entries {neighbor, weight}

