static int[] parent;

static int find(int x) {                       // representative of x's set
    return parent[x] == x ? x : (parent[x] = find(parent[x]));   // path compression
}

static boolean union(int a, int b) {           // false if already connected
    int ra = find(a), rb = find(b);
    if (ra == rb) return false;
    parent[ra] = rb;
    return true;
}
// init: parent[i] = i for every i

static int kruskal(int n, int[][] edges) {              // edges: {u, v, weight}
    Arrays.sort(edges, (a, b) -> a[2] - b[2]);
    parent = new int[n];
    for (int i = 0; i < n; i++) parent[i] = i;
    int total = 0;
    for (int[] e : edges)
        if (union(e[0], e[1])) total += e[2];            // only edges that join two components
    return total;
}
// graph from the Dijkstra lesson -> MST weight 7  (edges 0-2:1, 1-3:1, 2-1:2, 3-4:3)

static long power(long base, int exp) {
    if (exp == 0) return 1;                       // base case
    long half = power(base, exp / 2);             // solve a problem of half the size
    return (exp % 2 == 0) ? half * half : half * half * base;
}
// power(2, 10) -> 1024, power(3, 5) -> 243

