-- Originally the app queried: SELECT name, email FROM student;
-- We split contact details into a separate table:
CREATE TABLE student_contact (
  roll_no INT PRIMARY KEY REFERENCES student(roll_no),
  email   VARCHAR(100)
);

-- Recreate the old shape so existing app code keeps working
CREATE VIEW student_v AS
SELECT s.roll_no, s.name, c.email
FROM student s JOIN student_contact c ON c.roll_no = s.roll_no;

-- Entities: Department, Professor, Student, Course
-- Professor WORKS_IN Department (N:1)
-- Course OFFERED_BY Department (N:1)
-- Student ENROLLS_IN Course (M:N, attribute grade)

CREATE TABLE department (
  dept_id   INT PRIMARY KEY,
  dept_name VARCHAR(50) NOT NULL UNIQUE
);

CREATE TABLE professor (
  prof_id INT PRIMARY KEY,
  name    VARCHAR(50) NOT NULL,
  dept_id INT NOT NULL REFERENCES department(dept_id)  -- 1:N -> FK on N side
);

CREATE TABLE course (
  course_id VARCHAR(10) PRIMARY KEY,
  title     VARCHAR(100) NOT NULL,
  dept_id   INT NOT NULL REFERENCES department(dept_id)
);

CREATE TABLE student (
  roll_no INT PRIMARY KEY,
  name    VARCHAR(50) NOT NULL
);

CREATE TABLE enrollment (                         -- M:N -> junction table
  roll_no   INT         REFERENCES student(roll_no),
  course_id VARCHAR(10) REFERENCES course(course_id),
  grade     CHAR(2),
  PRIMARY KEY (roll_no, course_id)
);

START TRANSACTION;           -- BEGIN in PostgreSQL

UPDATE account SET balance = balance - 500 WHERE acc_no = 'A';
UPDATE account SET balance = balance + 500 WHERE acc_no = 'B';

-- If both succeeded:
COMMIT;
-- If anything failed instead:
-- ROLLBACK;

-- Partial rollback inside a long transaction
START TRANSACTION;
INSERT INTO orders VALUES (1, 'pending');
SAVEPOINT after_order;
INSERT INTO payments VALUES (1, 999);   -- suppose this fails
ROLLBACK TO SAVEPOINT after_order;      -- the order insert is kept
COMMIT;

SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;

-- Lost-update fix 1: do the arithmetic inside the database (atomic)
UPDATE product SET stock = stock - 1 WHERE id = 7 AND stock > 0;

-- Lost-update fix 2: lock the row while you read it
START TRANSACTION;
SELECT stock FROM product WHERE id = 7 FOR UPDATE;
-- ... application logic ...
UPDATE product SET stock = 9 WHERE id = 7;
COMMIT;

-- B+ tree index (the default in MySQL InnoDB and PostgreSQL)
CREATE INDEX idx_student_email ON student(email);

-- Composite index: leftmost-prefix rule
CREATE INDEX idx_dept_salary ON employee(dept_id, salary);
-- Can use the index:   WHERE dept_id = 5
-- Can use the index:   WHERE dept_id = 5 AND salary > 50000
-- Can't use it well:   WHERE salary > 50000   (skips the leftmost column)

-- Check whether the index is used
EXPLAIN SELECT * FROM employee WHERE dept_id = 5 AND salary > 50000;

#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    pid_t pid = fork();          // one process calls it, two return from it
    if (pid < 0) {
        perror("fork failed");
    } else if (pid == 0) {
        // child: fork() returned 0
        execlp("ls", "ls", "-l", NULL);   // replace child's image with ls
    } else {
        // parent: fork() returned the child's PID
        wait(NULL);              // wait for the child to finish
        printf("Child done\n");
    }
    return 0;
}

public class Demo {
