bool flag[2] = {false, false};   // flag[i]: process i wants to enter
int turn;                        // whose turn it is to yield

void enter(int i) {
    int j = 1 - i;
    flag[i] = true;              // I want to enter
    turn = j;                    // but you go first if you also want to
    while (flag[j] && turn == j)
        ;                        // busy wait
}

void leave(int i) {
    flag[i] = false;
}

// Test-and-Set: atomically return the old value and set the flag to true
bool test_and_set(bool *target) {
    bool old = *target;
    *target = true;
    return old;
}

// Spinlock built on it
while (test_and_set(&lock))
    ;                 // spin until the old value was false
/* critical section */
lock = false;

// Compare-and-Swap: set *value = new_val only if *value == expected
int compare_and_swap(int *value, int expected, int new_val) {
    int old = *value;
    if (old == expected) *value = new_val;
    return old;
}

// S is an integer accessed only through these atomic operations
wait(S) {          // also called P(), down()
    S--;
    if (S < 0) block this process;   // add it to S's waiting queue
}

signal(S) {        // also called V(), up()
    S++;
    if (S <= 0) wake up one waiting process;
}

semaphore mutex = 1;   // protects the buffer
semaphore empty = N;   // free slots
semaphore full  = 0;   // filled slots

producer() {
    while (true) {
        item = produce();
        wait(empty);       // wait for a free slot
        wait(mutex);
        add_to_buffer(item);
        signal(mutex);
        signal(full);      // one more item available
    }
}

consumer() {
    while (true) {
        wait(full);        // wait for an item
        wait(mutex);
        item = remove_from_buffer();
        signal(mutex);
        signal(empty);     // one more free slot
        consume(item);
    }
}

semaphore rw_mutex = 1;   // exclusive access for writers
semaphore mutex = 1;      // protects read_count
int read_count = 0;

writer() {
    wait(rw_mutex);
    /* write */
    signal(rw_mutex);
}

reader() {
    wait(mutex);
    read_count++;
    if (read_count == 1) wait(rw_mutex);   // first reader locks out writers
    signal(mutex);
    /* read (many readers at once) */
    wait(mutex);
    read_count--;
    if (read_count == 0) signal(rw_mutex); // last reader lets writers in
    signal(mutex);
}

class BoundedBuffer {
    private final int[] items = new int[10];
    private int count, putIdx, takeIdx;

    public synchronized void put(int x) throws InterruptedException {
        while (count == items.length) wait();   // buffer full
        items[putIdx] = x; putIdx = (putIdx + 1) % items.length; count++;
        notifyAll();                            // wake waiting consumers
    }

    public synchronized int take() throws InterruptedException {
        while (count == 0) wait();              // buffer empty
        int x = items[takeIdx]; takeIdx = (takeIdx + 1) % items.length; count--;
        notifyAll();
        return x;
    }
}
